import{_ as a,o as t,c as o,a3 as d}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Leave Management — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Leave Management — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/leave-management"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Leave Management — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/leave-management"}]]},"headers":[],"relativePath":"developer-guide/leave-management.md","filePath":"developer-guide/leave-management.md","lastUpdated":1786121823000}'),n={name:"developer-guide/leave-management.md"};function i(s,e,l,c,r,p){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="leave-management-—-developer-guide" tabindex="-1">Leave Management — Developer Guide <a class="header-anchor" href="#leave-management-—-developer-guide" aria-label="Permalink to &quot;Leave Management — Developer Guide&quot;">​</a></h1><p>Slug <code>leave-management</code>, middleware <code>module:leave-management</code>, permissions <code>leave-management.*</code>. Hard-depends on <code>employees</code>.</p><h2 id="domain" tabindex="-1">Domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;Domain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Table</th><th>Notes</th></tr></thead><tbody><tr><td><code>LeaveType</code></td><td><code>leave_types</code></td><td>Unique code per tenant; soft deletes</td></tr><tr><td><code>LeaveBalance</code></td><td><code>leave_balances</code></td><td>Unique employee+type+year; <code>syncRemaining()</code></td></tr><tr><td><code>LeaveRequest</code></td><td><code>leave_requests</code></td><td>Status machine; soft deletes; nullable <code>deduct_salary</code> until approve</td></tr></tbody></table><p>Enum: <code>LeaveRequestStatusEnum</code> — <code>draft</code> → <code>pending</code> → <code>approved</code> | <code>rejected</code>; draft/pending → <code>cancelled</code>.</p><p>Services: <code>LeaveTypeService</code>, <code>LeaveBalanceService</code>, <code>LeaveRequestService</code>. Approve runs under <code>lockForUpdate()</code>, sets <code>deduct_salary</code> (default <code>!leaveType.is_paid</code>), and calls <code>LeaveBalanceService::applyApprovedDays</code>.</p><h2 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h2><p><code>LeaveRequestPolicy</code>:</p><ul><li><code>canCreateForOthers</code> — <code>superadmin</code> / <code>admin</code> only (not manager)</li><li>Staff/managers create, update, submit, and cancel only for their linked active employee</li><li>Managers (with <code>leave-management.approve</code>) can approve/reject any pending request</li><li>Index scoped via <code>LeaveRequestService::query</code> for actors who cannot view all</li></ul><p>Default <strong>staff</strong> role includes <code>leave-management.view|create|update</code> (additive migration syncs existing workspaces). Those create/update grants apply to <strong>leave requests</strong> only: <code>LeaveTypePolicy</code> / <code>LeaveBalancePolicy</code> require admin/owner (<code>canManageCatalog</code>) for writes. Staff leave-balance lists are scoped to the linked employee; managers with <code>leave-management.approve</code> can view all balances.</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Models</td><td><code>LeaveType</code>, <code>LeaveBalance</code>, <code>LeaveRequest</code></td></tr><tr><td>Controllers</td><td><code>LeaveTypeController</code>, <code>LeaveBalanceController</code>, <code>LeaveRequestController</code></td></tr><tr><td>Requests</td><td><code>app/Http/Requests/Tenant/Api/V1/Leave{Type,Balance,Request}/*</code></td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Leave/</code></td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>leave-management.view | create | update | delete | restore | force.delete | approve</span></span></code></pre></div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>See <a href="/api/tenant-v1-leave-management">tenant-v1-leave-management.md</a>.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>API clients: <code>leaveTypeService</code>, <code>leaveBalanceService</code>, <code>leaveRequestService</code> in <code>src/api/services.ts</code></li><li>Keys / permissions: <code>QUERY_KEYS.leave*</code>, <code>PERMISSIONS.leaveManagement</code></li><li>Nav under <strong>HR</strong> (module <code>leave-management</code>)</li><li>Form locks employee for non-admin; review dialog collects notes + deduct toggle</li></ul><h2 id="payroll-integration" tabindex="-1">Payroll integration <a class="header-anchor" href="#payroll-integration" aria-label="Permalink to &quot;Payroll integration&quot;">​</a></h2><p><code>PayPeriodCalculator</code> counts unpaid leave days from approved requests using <code>deduct_salary</code>, falling back to <code>!leaveType.is_paid</code> when <code>deduct_salary</code> is null (legacy rows).</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Leave</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Payroll/PayPeriodCalculatorTest.php</span></span></code></pre></div>`,22)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
